'use client';

import { useState } from 'react';
import { Button } from '@/components/ui/button';
import { Dialog } from '@/components/ui/dialog';
import { Field, InlineField } from '@/components/ui/field';
import { FormError } from '@/components/ui/form-error';
import { Input, Textarea } from '@/components/ui/input';
import { KeyValueEditor } from '@/components/ui/list-inputs';
import { Switch } from '@/components/ui/switch';
import type { CatalogItem } from '@/lib/api/types';
import { apiErrorsFor, focusFirstError, type FieldErrors } from '@/lib/forms';
import type { ItemInput } from './api';

interface Draft {
  sku: string;
  name: string;
  category: string;
  price: string;
  stock: string;
  available: boolean;
  description: string;
  tags: string;
  attributes: Record<string, string> | undefined;
  url: string;
  imageUrl: string;
}

const fromItem = (item?: CatalogItem): Draft => ({
  sku: item?.sku ?? '',
  name: item?.name ?? '',
  category: item?.category ?? '',
  price: item?.price === null || item?.price === undefined ? '' : String(item.price),
  stock: item?.stock === null || item?.stock === undefined ? '' : String(item.stock),
  available: item?.available ?? true,
  description: item?.description ?? '',
  tags: item?.tags.join(', ') ?? '',
  attributes: item && Object.keys(item.attributes).length ? item.attributes : undefined,
  url: item?.url ?? '',
  imageUrl: item?.imageUrl ?? '',
});

const isHttpUrl = (value: string) => /^https?:\/\/\S+$/i.test(value);

/** The draft as an API body, or the problems to fix (same rules as the API). */
export function toItemInput(draft: Draft): { ok: true; value: ItemInput } | { ok: false; errors: FieldErrors } {
  const errors: FieldErrors = {};
  if (!draft.name.trim()) errors.name = 'Give the item a name';
  const price = draft.price.trim().replace(/,/g, '');
  if (price && !/^\d+(\.\d{1,2})?$/.test(price)) errors.price = 'A number with at most two decimals, e.g. 1250 or 12.50';
  const stock = draft.stock.trim();
  if (stock && !/^\d+$/.test(stock)) errors.stock = 'A whole number, or empty when stock is not tracked';
  for (const field of ['url', 'imageUrl'] as const) if (draft[field].trim() && !isHttpUrl(draft[field].trim())) errors[field] = 'An http(s) address';
  if (Object.keys(errors).length) return { ok: false, errors };
  return {
    ok: true,
    value: {
      ...(draft.sku.trim() ? { sku: draft.sku.trim() } : {}),
      name: draft.name.trim(),
      description: draft.description.trim(),
      category: draft.category.trim() || null,
      price: price ? Number(price) : null,
      stock: stock ? Number(stock) : null,
      available: draft.available,
      tags: [...new Set(draft.tags.split(',').map((t) => t.trim()).filter(Boolean))],
      attributes: draft.attributes ?? {},
      url: draft.url.trim() || null,
      imageUrl: draft.imageUrl.trim() || null,
    },
  };
}

/** Add an item, or edit one. Empty SKU on a new item: the API makes one from the name. */
export function ItemDialog({ item, currency, onOpenChange, onSave }: { item?: CatalogItem; currency: string; onOpenChange: (open: boolean) => void; onSave: (body: ItemInput) => Promise<unknown> }) {
  const [draft, setDraft] = useState<Draft>(() => fromItem(item));
  const [errors, setErrors] = useState<FieldErrors>({});
  const [busy, setBusy] = useState(false);
  const [form, setForm] = useState<HTMLFormElement | null>(null);
  const set = <K extends keyof Draft>(key: K, value: Draft[K]) => setDraft((d) => ({ ...d, [key]: value }));

  const submit = async () => {
    const result = toItemInput(draft);
    if (!result.ok) {
      setErrors(result.errors);
      focusFirstError(form);
      return;
    }
    setBusy(true);
    try {
      await onSave(result.value);
      onOpenChange(false);
    } catch (error) {
      setErrors(apiErrorsFor(error));
      focusFirstError(form);
    } finally {
      setBusy(false);
    }
  };

  return (
    <Dialog
      open
      onOpenChange={onOpenChange}
      size="lg"
      title={item ? `Edit ${item.name}` : 'Add an item'}
      description={`Prices are in ${currency}.`}
      footer={
        <>
          <Button variant="secondary" onClick={() => onOpenChange(false)} disabled={busy}>
            Cancel
          </Button>
          <Button variant="primary" loading={busy} onClick={() => void submit()}>
            {item ? 'Save item' : 'Add item'}
          </Button>
        </>
      }
    >
      <form
        ref={setForm}
        className="grid gap-4 sm:grid-cols-2"
        onSubmit={(e) => {
          e.preventDefault();
          void submit();
        }}
      >
        <div className="sm:col-span-2">
          <FormError errors={errors} shown={['name', 'sku', 'category', 'price', 'stock', 'description', 'tags', 'url', 'imageUrl']} />
        </div>
        <Field label="Name" required error={errors.name} className="sm:col-span-2">
          {(props) => <Input {...props} value={draft.name} maxLength={300} onChange={(e) => set('name', e.target.value)} />}
        </Field>
        <Field label="SKU" description={item ? 'Your product code; imports match items by it.' : 'Your product code. Leave empty to make one from the name.'} error={errors.sku}>
          {(props) => <Input {...props} value={draft.sku} maxLength={100} onChange={(e) => set('sku', e.target.value)} />}
        </Field>
        <Field label="Category" error={errors.category}>
          {(props) => <Input {...props} value={draft.category} maxLength={200} placeholder="Shoes" onChange={(e) => set('category', e.target.value)} />}
        </Field>
        <Field label={`Price (${currency})`} description="Empty when the price is on request." error={errors.price}>
          {(props) => <Input {...props} inputMode="decimal" value={draft.price} onChange={(e) => set('price', e.target.value)} />}
        </Field>
        <Field label="Stock" description="Units on hand. Empty when you do not track stock." error={errors.stock}>
          {(props) => <Input {...props} inputMode="numeric" value={draft.stock} onChange={(e) => set('stock', e.target.value)} />}
        </Field>
        <InlineField label="Available to order" description="Off: the assistant says it is not available, even with stock." className="sm:col-span-2">
          {(props) => <Switch {...props} checked={draft.available} onCheckedChange={(checked) => set('available', checked)} />}
        </InlineField>
        <Field label="Description" description="What the assistant can tell customers about it." error={errors.description} className="sm:col-span-2">
          {(props) => <Textarea {...props} rows={3} value={draft.description} maxLength={5000} onChange={(e) => set('description', e.target.value)} />}
        </Field>
        <Field label="Tags" description="Comma separated: other words customers use for it." error={errors.tags} className="sm:col-span-2">
          {(props) => <Input {...props} value={draft.tags} placeholder="running, road" onChange={(e) => set('tags', e.target.value)} />}
        </Field>
        <fieldset className="flex flex-col gap-2 sm:col-span-2">
          <legend className="text-sm font-medium text-text">Attributes</legend>
          <p className="text-xs text-muted">Size, colour, brand, weight…</p>
          <KeyValueEditor idPrefix="item-attr" value={draft.attributes} onChange={(value) => set('attributes', value)} keyLabel="Attribute" valueLabel="Value" addLabel="Add attribute" />
        </fieldset>
        <Field label="Product page" error={errors.url}>
          {(props) => <Input {...props} type="url" value={draft.url} placeholder="https://" onChange={(e) => set('url', e.target.value)} />}
        </Field>
        <Field label="Image address" error={errors.imageUrl}>
          {(props) => <Input {...props} type="url" value={draft.imageUrl} placeholder="https://" onChange={(e) => set('imageUrl', e.target.value)} />}
        </Field>
        <button type="submit" hidden />
      </form>
    </Dialog>
  );
}
