'use client';

import { FileUp } from 'lucide-react';
import { useState } from 'react';
import { Button } from '@/components/ui/button';
import { Dialog } from '@/components/ui/dialog';
import { Field } from '@/components/ui/field';
import { FormError } from '@/components/ui/form-error';
import { Textarea } from '@/components/ui/input';
import { useToast } from '@/components/ui/toast';
import type { CatalogImportReport } from '@/lib/api/types';
import { apiErrorsFor, type FieldErrors } from '@/lib/forms';
import { readTextFile, type ImportInput } from './api';

/** File or pasted text → the import body: CSV text, or JSON items (an array, or {"items": [...]}) . */
export function importBody(text: string, fileName: string | null): { ok: true; body: Pick<ImportInput, 'csv' | 'items'> } | { ok: false; error: string } {
  const trimmed = text.trim();
  if (!trimmed) return { ok: false, error: 'Choose a file or paste the rows first' };
  const looksJson = fileName?.toLowerCase().endsWith('.json') || trimmed.startsWith('[') || trimmed.startsWith('{');
  if (!looksJson) return { ok: true, body: { csv: text } };
  try {
    const parsed: unknown = JSON.parse(trimmed);
    const items = Array.isArray(parsed) ? parsed : (parsed as { items?: unknown })?.items;
    if (!Array.isArray(items) || !items.length || !items.every((i) => typeof i === 'object' && i !== null && !Array.isArray(i))) {
      return { ok: false, error: 'JSON must be a list of items, e.g. [{"sku": "A1", "name": "Tea", "price": 120}]' };
    }
    return { ok: true, body: { items: items as Record<string, unknown>[] } };
  } catch {
    return { ok: false, error: 'This is not valid JSON' };
  }
}

const SAMPLE = 'sku,name,category,price,stock,description\nSH-41,Running shoes Pegasus 41,Shoes,8500,12,Light road running shoe';

function ReportSummary({ report }: { report: CatalogImportReport }) {
  const parts = [
    `${report.created} new`,
    `${report.updated} updated`,
    ...(report.mode === 'replace' ? [`${report.removed} removed`] : []),
    `${report.rejectedCount} skipped`,
  ];
  return (
    <div className="flex flex-col gap-3" aria-live="polite">
      <p className="text-sm text-text">
        <span className="font-semibold">{report.totalRows} rows read:</span> {parts.join(' · ')}.
      </p>
      {report.attributeColumns.length ? <p className="text-xs text-muted">Kept as attributes: {report.attributeColumns.join(', ')}.</p> : null}
      {report.mode === 'replace' && report.removed > 0 ? (
        <p role="alert" className="rounded-md border border-warning/40 bg-warning-soft px-3 py-2 text-sm text-text">
          {report.removed} item(s) not in this file will be removed from the catalog.
        </p>
      ) : null}
      {report.rejected.length ? (
        <div>
          <h3 className="mb-1 text-sm font-medium text-text">Rows that will be skipped</h3>
          <ul className="max-h-48 overflow-y-auto rounded-md border border-border text-sm">
            {report.rejected.slice(0, 50).map((r) => (
              <li key={`${r.row}-${r.reason}`} className="border-b border-border px-3 py-1.5 last:border-b-0">
                <span className="font-medium tabular-nums">Row {r.row}:</span> {r.reason}
              </li>
            ))}
          </ul>
          {report.rejectedCount > 50 ? <p className="mt-1 text-xs text-muted">…and {report.rejectedCount - 50} more.</p> : null}
        </div>
      ) : null}
    </div>
  );
}

/**
 * Import items from CSV or JSON in two steps: check (a dry run: what would be added, updated,
 * removed and skipped), then import. Nothing is saved until the second step.
 */
export function ImportDialog({ onOpenChange, onImport }: { onOpenChange: (open: boolean) => void; onImport: (body: ImportInput) => Promise<CatalogImportReport> }) {
  const toast = useToast();
  const [text, setText] = useState('');
  const [fileName, setFileName] = useState<string | null>(null);
  const [mode, setMode] = useState<'upsert' | 'replace'>('upsert');
  const [report, setReport] = useState<CatalogImportReport | null>(null);
  const [errors, setErrors] = useState<FieldErrors>({});
  const [busy, setBusy] = useState(false);

  const run = async (dryRun: boolean) => {
    const parsed = importBody(text, fileName);
    if (!parsed.ok) {
      setErrors({ file: parsed.error });
      return;
    }
    setErrors({});
    setBusy(true);
    try {
      const result = await onImport({ ...parsed.body, mode, dryRun });
      if (dryRun) {
        setReport(result);
      } else {
        toast.success('Import finished', `${result.created} added, ${result.updated} updated${result.removed ? `, ${result.removed} removed` : ''}${result.rejectedCount ? `, ${result.rejectedCount} skipped` : ''}.`);
        onOpenChange(false);
      }
    } catch (error) {
      setErrors(apiErrorsFor(error));
      setReport(null);
    } finally {
      setBusy(false);
    }
  };

  const changed = () => setReport(null);
  const importable = report ? report.created + report.updated + report.removed : 0;

  return (
    <Dialog
      open
      onOpenChange={onOpenChange}
      size="lg"
      title="Import items"
      description="From a spreadsheet saved as CSV (UTF-8, header in the first row) or a JSON list. Items are matched by SKU: new ones are added, known ones updated."
      footer={
        <>
          <Button variant="secondary" onClick={() => onOpenChange(false)} disabled={busy}>
            Cancel
          </Button>
          {report ? (
            <Button variant="primary" loading={busy} disabled={importable === 0} onClick={() => void run(false)}>
              {mode === 'replace' ? 'Replace catalog' : `Import ${report.created + report.updated} items`}
            </Button>
          ) : (
            <Button variant="primary" loading={busy} onClick={() => void run(true)}>
              Check file
            </Button>
          )}
        </>
      }
    >
      <div className="flex flex-col gap-4">
        <FormError errors={errors} shown={['file']} />
        <div className="flex flex-col gap-1.5">
          <label htmlFor="import-file" className="text-sm font-medium text-text">
            File
          </label>
          <div className="flex flex-wrap items-center gap-2">
            <label htmlFor="import-file" className="inline-flex h-10 cursor-pointer items-center gap-2 rounded-md border border-control bg-surface px-3 text-sm font-medium text-text hover:bg-surface-2">
              <FileUp aria-hidden="true" className="size-4" />
              Choose a file
            </label>
            <input
              id="import-file"
              type="file"
              accept=".csv,.json,.txt,text/csv,application/json"
              className="sr-only"
              onChange={async (e) => {
                const file = e.target.files?.[0];
                if (!file) return;
                const read = await readTextFile(file);
                changed();
                if ('error' in read) {
                  setErrors({ file: read.error });
                  return;
                }
                setFileName(file.name);
                setText(read.text);
                setErrors({});
              }}
            />
            <span className="text-sm text-muted">{fileName ?? 'No file chosen'}</span>
          </div>
        </div>
        <Field label="Or paste the rows" description="Columns are recognised by name: sku, name, description, category, price, stock (or quantity), available, tags, url, image. Other columns become attributes (size, colour…)." error={errors.file}>
          {(props) => (
            <Textarea
              {...props}
              rows={6}
              className="font-mono text-xs"
              placeholder={SAMPLE}
              value={text}
              onChange={(e) => {
                setText(e.target.value);
                setFileName(null);
                changed();
              }}
            />
          )}
        </Field>
        <fieldset className="flex flex-col gap-2">
          <legend className="text-sm font-medium text-text">Items not in the file</legend>
          <label className="flex items-start gap-2 text-sm">
            <input type="radio" name="import-mode" className="mt-1" checked={mode === 'upsert'} onChange={() => (setMode('upsert'), changed())} />
            <span>
              <span className="font-medium">Keep them</span>
              <span className="block text-xs text-muted">Add new items and update the ones in the file. An update changes only the columns the file has.</span>
            </span>
          </label>
          <label className="flex items-start gap-2 text-sm">
            <input type="radio" name="import-mode" className="mt-1" checked={mode === 'replace'} onChange={() => (setMode('replace'), changed())} />
            <span>
              <span className="font-medium">Remove them</span>
              <span className="block text-xs text-muted">The file becomes the whole catalog.</span>
            </span>
          </label>
        </fieldset>
        {report ? <ReportSummary report={report} /> : null}
      </div>
    </Dialog>
  );
}
