'use client';

import { FileUp, MoreHorizontal, Pencil, Plus, Search, ShoppingBag, Trash2 } from 'lucide-react';
import Link from 'next/link';
import { useRouter } from 'next/navigation';
import { useState } from 'react';
import { Button, IconButton } from '@/components/ui/button';
import { Card, CardBody, CardHeader } from '@/components/ui/card';
import { ConfirmDialog } from '@/components/ui/dialog';
import { Checkbox, Input, Select } from '@/components/ui/input';
import { LoadMore } from '@/components/ui/load-more';
import { Menu, MenuItem } from '@/components/ui/menu';
import { PageBody, PageHeader } from '@/components/ui/page';
import { EmptyState, ErrorState, LoadingState } from '@/components/ui/states';
import { Table, TBody, Td, Th, THead, Tr } from '@/components/ui/table';
import { useToast } from '@/components/ui/toast';
import type { Catalog, CatalogItem } from '@/lib/api/types';
import { formatNumber } from '@/lib/format';
import { useSession } from '@/lib/session';
import { useDebounced } from '@/lib/use-debounced';
import { useCatalog, useCatalogItems, useCatalogMutations, useProductSearch } from './api';
import { ImportDialog } from './import-dialog';
import { ItemDialog } from './item-dialog';
import { AvailabilityBadge, formatPrice, NameDialog } from './shared';

/** Type what a customer might ask for and see what the assistant's catalog search returns. */
function TestSearch({ catalog }: { catalog: Catalog }) {
  const [q, setQ] = useState('');
  const [maxPrice, setMaxPrice] = useState('');
  const [inStockOnly, setInStockOnly] = useState(false);
  const term = useDebounced(q);
  const budget = /^\d+(\.\d+)?$/.test(maxPrice.trim()) ? Number(maxPrice) : undefined;
  const search = useProductSearch(catalog.id, { q: term.trim(), maxPrice: budget, inStockOnly }, term.trim().length > 0);
  return (
    <Card>
      <CardHeader title="Try the assistant's search" description="What a large catalog's search returns during a conversation. The assistant writes the query in the catalog's words, even when the customer speaks another language." />
      <CardBody className="flex flex-col gap-3">
        <div className="flex flex-wrap items-end gap-3">
          <div className="min-w-48 flex-1">
            <label htmlFor="test-search" className="mb-1.5 block text-sm font-medium text-text">
              Query
            </label>
            <Input id="test-search" type="search" placeholder="waterproof running shoes" value={q} onChange={(e) => setQ(e.target.value)} />
          </div>
          <div className="w-36">
            <label htmlFor="test-budget" className="mb-1.5 block text-sm font-medium text-text">
              Budget ({catalog.currency})
            </label>
            <Input id="test-budget" inputMode="decimal" value={maxPrice} onChange={(e) => setMaxPrice(e.target.value)} />
          </div>
          <div className="flex h-10 items-center gap-2">
            <Checkbox id="test-in-stock" checked={inStockOnly} onChange={(e) => setInStockOnly(e.target.checked)} />
            <label htmlFor="test-in-stock" className="text-sm text-text">
              Only orderable
            </label>
          </div>
        </div>
        {!term.trim() ? null : search.isPending ? (
          <LoadingState label="Searching…" rows={2} />
        ) : search.isError ? (
          <ErrorState error={search.error} title="Search failed" onRetry={() => void search.refetch()} />
        ) : search.data.data.length === 0 ? (
          <p className="text-sm text-muted" role="status">
            Nothing matches. The assistant would say this is not available.
          </p>
        ) : (
          <ol aria-label="Search results" className="flex flex-col divide-y divide-border rounded-md border border-border">
            {search.data.data.map((hit) => (
              <li key={hit.itemId} className="flex flex-wrap items-center justify-between gap-2 px-3 py-2">
                <span className="min-w-0">
                  <span className="text-sm font-medium text-text">{hit.name}</span>
                  <span className="ml-2 text-xs text-muted">{hit.sku}</span>
                </span>
                <span className="flex items-center gap-2 text-sm">
                  <span className="tabular-nums">{formatPrice(hit.price, hit.currency)}</span>
                  <span className="text-muted">· {hit.availability}</span>
                </span>
              </li>
            ))}
          </ol>
        )}
      </CardBody>
    </Card>
  );
}

function ItemRow({ item, catalog, canManage, onEdit, onDelete }: { item: CatalogItem; catalog: Catalog; canManage: boolean; onEdit: () => void; onDelete: () => void }) {
  return (
    <Tr>
      <Td>
        {canManage ? (
          <button type="button" onClick={onEdit} className="text-left font-medium text-accent-text underline-offset-4 hover:underline">
            {item.name}
          </button>
        ) : (
          <span className="font-medium text-text">{item.name}</span>
        )}
        <p className="text-xs text-muted">{item.sku}</p>
      </Td>
      <Td className="hidden text-muted sm:table-cell">{item.category ?? '—'}</Td>
      <Td className="text-right tabular-nums">{formatPrice(item.price, catalog.currency)}</Td>
      <Td>
        <AvailabilityBadge item={item} />
      </Td>
      {canManage ? (
        <Td className="w-12 text-right">
          <Menu label={`Actions for ${item.name}`} trigger={<IconButton label={`Actions for ${item.name}`} icon={<MoreHorizontal />} />}>
            <MenuItem onSelect={onEdit}>
              <Pencil aria-hidden="true" />
              Edit
            </MenuItem>
            <MenuItem tone="danger" onSelect={onDelete}>
              <Trash2 aria-hidden="true" />
              Delete
            </MenuItem>
          </Menu>
        </Td>
      ) : null}
    </Tr>
  );
}

export function CatalogDetail({ id }: { id: string }) {
  const { can } = useSession();
  const router = useRouter();
  const toast = useToast();
  const catalog = useCatalog(id);
  const [search, setSearch] = useState('');
  const [category, setCategory] = useState('');
  const term = useDebounced(search);
  const items = useCatalogItems(id, { search: term, category });
  const mutations = useCatalogMutations(id);
  const canManage = can('knowledge:manage');
  const [dialog, setDialog] = useState<null | { kind: 'import' } | { kind: 'item'; item?: CatalogItem } | { kind: 'rename' } | { kind: 'delete' } | { kind: 'delete-item'; item: CatalogItem }>(null);
  const close = (open: boolean) => (open ? undefined : setDialog(null));

  if (catalog.isPending) {
    return (
      <PageBody>
        <LoadingState label="Loading catalog…" />
      </PageBody>
    );
  }
  if (catalog.isError) {
    return (
      <PageBody>
        <ErrorState error={catalog.error} title="Could not load this catalog" onRetry={() => void catalog.refetch()} />
      </PageBody>
    );
  }
  const data = catalog.data;
  const filtered = Boolean(term.trim() || category);

  return (
    <PageBody>
      <PageHeader
        breadcrumb={
          <Link href="/catalogs" className="hover:underline">
            Catalogs
          </Link>
        }
        title={data.name}
        description={`${formatNumber(data.itemCount)} items · prices in ${data.currency} · used by ${data.assistantCount === 1 ? '1 assistant' : `${data.assistantCount ?? 0} assistants`}${data.description ? ` · ${data.description}` : ''}`}
        actions={
          canManage ? (
            <>
              <Button onClick={() => setDialog({ kind: 'import' })}>
                <FileUp aria-hidden="true" />
                Import
              </Button>
              <Button variant="primary" onClick={() => setDialog({ kind: 'item' })}>
                <Plus aria-hidden="true" />
                Add item
              </Button>
              <Menu label="Catalog actions" trigger={<IconButton label="Catalog actions" icon={<MoreHorizontal />} variant="secondary" size="md" />}>
                <MenuItem onSelect={() => setDialog({ kind: 'rename' })}>
                  <Pencil aria-hidden="true" />
                  Rename or change currency
                </MenuItem>
                <MenuItem tone="danger" onSelect={() => setDialog({ kind: 'delete' })}>
                  <Trash2 aria-hidden="true" />
                  Delete catalog
                </MenuItem>
              </Menu>
            </>
          ) : null
        }
      />

      <div className="flex flex-col gap-6">
        <section aria-labelledby="items-heading" className="flex flex-col gap-3">
          <h2 id="items-heading" className="sr-only">
            Items
          </h2>
          <div className="flex flex-wrap gap-3">
            <div className="relative max-w-sm min-w-48 flex-1">
              <label htmlFor="item-search" className="sr-only">
                Search items
              </label>
              <Search aria-hidden="true" className="pointer-events-none absolute top-1/2 left-3 size-4 -translate-y-1/2 text-muted" />
              <Input id="item-search" type="search" placeholder="Name, SKU or words" value={search} onChange={(e) => setSearch(e.target.value)} className="pl-9" />
            </div>
            {data.categories?.length ? (
              <div className="w-48">
                <label htmlFor="item-category" className="sr-only">
                  Category
                </label>
                <Select id="item-category" value={category} onChange={(e) => setCategory(e.target.value)}>
                  <option value="">All categories</option>
                  {data.categories.map((c) => (
                    <option key={c.name} value={c.name}>
                      {c.name} ({c.itemCount})
                    </option>
                  ))}
                </Select>
              </div>
            ) : null}
          </div>
          {items.isPending ? (
            <LoadingState label="Loading items…" />
          ) : items.isError ? (
            <ErrorState error={items.error} title="Could not load items" onRetry={() => void items.refetch()} />
          ) : items.items.length === 0 ? (
            filtered ? (
              <EmptyState icon={<Search />} title="No items match" description="Try other words or another category." />
            ) : (
              <EmptyState
                icon={<ShoppingBag />}
                title="This catalog is empty"
                description="Import your products from a spreadsheet saved as CSV, or add them one by one."
                action={
                  canManage ? (
                    <Button variant="primary" onClick={() => setDialog({ kind: 'import' })}>
                      <FileUp aria-hidden="true" />
                      Import items
                    </Button>
                  ) : null
                }
              />
            )
          ) : (
            <>
              <Table label="Items">
                <THead>
                  <Tr>
                    <Th>Item</Th>
                    <Th className="hidden sm:table-cell">Category</Th>
                    <Th className="text-right">Price</Th>
                    <Th>Availability</Th>
                    {canManage ? (
                      <Th className="w-12">
                        <span className="sr-only">Actions</span>
                      </Th>
                    ) : null}
                  </Tr>
                </THead>
                <TBody>
                  {items.items.map((item) => (
                    <ItemRow key={item.id} item={item} catalog={data} canManage={canManage} onEdit={() => setDialog({ kind: 'item', item })} onDelete={() => setDialog({ kind: 'delete-item', item })} />
                  ))}
                </TBody>
              </Table>
              <LoadMore count={items.items.length} noun="item" hasNextPage={items.hasNextPage} isFetchingNextPage={items.isFetchingNextPage} fetchNextPage={items.fetchNextPage} />
            </>
          )}
        </section>

        {data.itemCount > 0 ? <TestSearch catalog={data} /> : null}
      </div>

      {dialog?.kind === 'import' ? <ImportDialog onOpenChange={close} onImport={(body) => mutations.importItems.mutateAsync(body)} /> : null}
      {dialog?.kind === 'item' ? (
        <ItemDialog
          item={dialog.item}
          currency={data.currency}
          onOpenChange={close}
          onSave={async (body) => {
            if (dialog.item) {
              await mutations.updateItem.mutateAsync({ itemId: dialog.item.id, body });
              toast.success('Item saved');
            } else {
              const created = await mutations.createItem.mutateAsync(body);
              toast.success('Item added', `SKU ${created.sku}`);
            }
          }}
        />
      ) : null}
      {dialog?.kind === 'rename' ? (
        <NameDialog
          open
          onOpenChange={close}
          title="Edit catalog"
          submitLabel="Save"
          withCurrency
          initial={{ name: data.name, description: data.description, currency: data.currency }}
          onSubmit={(value) => mutations.update.mutateAsync(value)}
        />
      ) : null}
      <ConfirmDialog
        open={dialog?.kind === 'delete'}
        onOpenChange={close}
        title={`Delete ${data.name}?`}
        description={`Its ${formatNumber(data.itemCount)} items are deleted too. Assistants that use it will answer without it.`}
        confirmLabel="Delete catalog"
        onConfirm={async () => {
          try {
            await mutations.remove.mutateAsync();
            toast.success('Catalog deleted');
            router.push('/catalogs');
          } catch (error) {
            toast.error('Could not delete the catalog', error);
            throw error;
          }
        }}
      />
      <ConfirmDialog
        open={dialog?.kind === 'delete-item'}
        onOpenChange={close}
        title={dialog?.kind === 'delete-item' ? `Delete ${dialog.item.name}?` : 'Delete item?'}
        description="Assistants stop offering it at once."
        confirmLabel="Delete item"
        onConfirm={async () => {
          if (dialog?.kind !== 'delete-item') return;
          try {
            await mutations.removeItem.mutateAsync(dialog.item.id);
            toast.success('Item deleted');
          } catch (error) {
            toast.error('Could not delete the item', error);
            throw error;
          }
        }}
      />
    </PageBody>
  );
}
